## `components/application-infrastructure.ts`

```typescript
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

export interface ApplicationInfrastructureArgs {
    environment: pulumi.Input<"dev" | "prod">;

    vpcId: pulumi.Input<string>;

    /**
     * Private subnets in at least two availability zones.
     */
    databaseSubnetIds: pulumi.Input<pulumi.Input<string>[]>;

    /**
     * Security group used by the application/EKS workload.
     * PostgreSQL ingress is restricted to this security group.
     */
    applicationSecurityGroupId: pulumi.Input<string>;

    databaseName: pulumi.Input<string>;
    databaseUsername: pulumi.Input<string>;

    /**
     * Must be supplied with Config.requireSecret().
     */
    databasePassword: pulumi.Input<string>;

    databaseInstanceClass: pulumi.Input<string>;
    databaseMultiAz: pulumi.Input<boolean>;
    databaseStorageEncrypted: pulumi.Input<boolean>;

    /**
     * ARN of the EKS IAM OIDC provider.
     */
    oidcProviderArn: pulumi.Input<string>;

    /**
     * OIDC issuer URL, with or without the https:// prefix.
     * Example:
     * https://oidc.eks.us-east-1.amazonaws.com/id/ABC123
     */
    oidcIssuerUrl: pulumi.Input<string>;

    serviceAccountNamespace: pulumi.Input<string>;
    serviceAccountName: pulumi.Input<string>;

    /**
     * Enables replication from the primary bucket to a replica bucket in
     * us-west-2. Intended for production.
     */
    enableCrossRegionReplication?: pulumi.Input<boolean>;

    tags?: pulumi.Input<Record<string, pulumi.Input<string>>>;
}

export class ApplicationInfrastructure extends pulumi.ComponentResource {
    public readonly assetsBucket: aws.s3.BucketV2;
    public readonly database: aws.rds.Instance;
    public readonly databaseSecurityGroup: aws.ec2.SecurityGroup;
    public readonly serviceAccountRole: aws.iam.Role;

    public readonly replicaBucket?: aws.s3.BucketV2;
    public readonly databaseConnectionString: pulumi.Output<string>;

    constructor(
        name: string,
        args: ApplicationInfrastructureArgs,
        opts?: pulumi.ComponentResourceOptions,
    ) {
        super(
            "example:components:ApplicationInfrastructure",
            name,
            {},
            opts,
        );

        const childOptions: pulumi.ResourceOptions = {
            parent: this,
        };

        const tags = pulumi
            .all([args.environment, args.tags])
            .apply(([environment, additionalTags]) => ({
                Environment: environment,
                Component: name,
                ManagedBy: "Pulumi",
                ...(additionalTags ?? {}),
            }));

        /*
         * Primary S3 bucket
         */

        this.assetsBucket = new aws.s3.BucketV2(
            `${name}-assets`,
            {
                tags,
            },
            childOptions,
        );

        const assetsVersioning = new aws.s3.BucketVersioningV2(
            `${name}-assets-versioning`,
            {
                bucket: this.assetsBucket.id,
                versioningConfiguration: {
                    status: "Enabled",
                },
            },
            childOptions,
        );

        new aws.s3.BucketServerSideEncryptionConfigurationV2(
            `${name}-assets-encryption`,
            {
                bucket: this.assetsBucket.id,
                rules: [{
                    applyServerSideEncryptionByDefault: {
                        sseAlgorithm: "AES256",
                    },
                    bucketKeyEnabled: true,
                }],
            },
            childOptions,
        );

        new aws.s3.BucketPublicAccessBlock(
            `${name}-assets-public-access`,
            {
                bucket: this.assetsBucket.id,
                blockPublicAcls: true,
                blockPublicPolicy: true,
                ignorePublicAcls: true,
                restrictPublicBuckets: true,
            },
            childOptions,
        );

        /*
         * PostgreSQL
         */

        const databaseSubnetGroup = new aws.rds.SubnetGroup(
            `${name}-db-subnets`,
            {
                subnetIds: args.databaseSubnetIds,
                tags,
            },
            childOptions,
        );

        this.databaseSecurityGroup = new aws.ec2.SecurityGroup(
            `${name}-db`,
            {
                vpcId: args.vpcId,
                description: "PostgreSQL access from the application workload",
                ingress: [{
                    protocol: "tcp",
                    fromPort: 5432,
                    toPort: 5432,
                    securityGroups: [args.applicationSecurityGroupId],
                    description: "PostgreSQL from application security group",
                }],
                egress: [],
                tags,
            },
            childOptions,
        );

        this.database = new aws.rds.Instance(
            `${name}-postgres`,
            {
                engine: "postgres",
                engineVersion: "16",
                instanceClass: args.databaseInstanceClass,

                allocatedStorage: 20,
                maxAllocatedStorage: 100,
                storageType: "gp3",
                storageEncrypted: args.databaseStorageEncrypted,

                dbName: args.databaseName,
                username: args.databaseUsername,
                password: args.databasePassword,
                port: 5432,

                dbSubnetGroupName: databaseSubnetGroup.name,
                vpcSecurityGroupIds: [this.databaseSecurityGroup.id],

                multiAz: args.databaseMultiAz,
                publiclyAccessible: false,

                deletionProtection: true,
                skipFinalSnapshot: false,
                finalSnapshotIdentifier: pulumi.interpolate`${name}-final-${pulumi.getStack()}`,

                backupRetentionPeriod: 7,
                backupWindow: "03:00-04:00",
                maintenanceWindow: "sun:04:00-sun:05:00",

                autoMinorVersionUpgrade: true,
                applyImmediately: false,
                copyTagsToSnapshot: true,

                tags,
            },
            {
                ...childOptions,

                // Adds a second layer of protection against accidental
                // `pulumi destroy` in production.
                protect: pulumi.getStack() === "prod",
            },
        );

        this.databaseConnectionString = pulumi.secret(
            pulumi
                .all([
                    args.databaseUsername,
                    args.databasePassword,
                    this.database.address,
                    this.database.port,
                    args.databaseName,
                ])
                .apply(([username, password, host, port, databaseName]) => {
                    const encodedUsername = encodeURIComponent(username);
                    const encodedPassword = encodeURIComponent(password);

                    return [
                        `postgresql://${encodedUsername}:${encodedPassword}`,
                        `@${host}:${port}/${databaseName}`,
                        "?sslmode=require",
                    ].join("");
                }),
        );

        /*
         * IAM role for the Kubernetes service account (IRSA)
         */

        const oidcIssuerWithoutScheme = pulumi
            .output(args.oidcIssuerUrl)
            .apply((issuer) => issuer.replace(/^https:\/\//, "").replace(/\/$/, ""));

        const assumeRolePolicy = pulumi
            .all([
                args.oidcProviderArn,
                oidcIssuerWithoutScheme,
                args.serviceAccountNamespace,
                args.serviceAccountName,
            ])
            .apply(([providerArn, issuer, namespace, serviceAccount]) =>
                aws.iam.getPolicyDocumentOutput({
                    statements: [{
                        effect: "Allow",
                        actions: ["sts:AssumeRoleWithWebIdentity"],
                        principals: [{
                            type: "Federated",
                            identifiers: [providerArn],
                        }],
                        conditions: [
                            {
                                test: "StringEquals",
                                variable: `${issuer}:aud`,
                                values: ["sts.amazonaws.com"],
                            },
                            {
                                test: "StringEquals",
                                variable: `${issuer}:sub`,
                                values: [
                                    `system:serviceaccount:${namespace}:${serviceAccount}`,
                                ],
                            },
                        ],
                    }],
                }).json,
            );

        this.serviceAccountRole = new aws.iam.Role(
            `${name}-service-account`,
            {
                assumeRolePolicy,
                description: "Least-privilege role for the application service account",
                tags,
            },
            childOptions,
        );

        const applicationPolicy = aws.iam.getPolicyDocumentOutput({
            statements: [
                {
                    sid: "ListApplicationAssets",
                    effect: "Allow",
                    actions: [
                        "s3:GetBucketLocation",
                        "s3:ListBucket",
                    ],
                    resources: [this.assetsBucket.arn],
                },
                {
                    sid: "ReadWriteApplicationAssets",
                    effect: "Allow",
                    actions: [
                        "s3:GetObject",
                        "s3:GetObjectVersion",
                        "s3:PutObject",
                        "s3:DeleteObject",
                    ],
                    resources: [
                        pulumi.interpolate`${this.assetsBucket.arn}/*`,
                    ],
                },
            ],
        });

        const serviceAccountPolicy = new aws.iam.Policy(
            `${name}-service-account`,
            {
                description: "Application-specific S3 permissions",
                policy: applicationPolicy.json,
                tags,
            },
            childOptions,
        );

        new aws.iam.RolePolicyAttachment(
            `${name}-service-account`,
            {
                role: this.serviceAccountRole.name,
                policyArn: serviceAccountPolicy.arn,
            },
            childOptions,
        );

        /*
         * Optional production cross-region S3 replication.
         */

        const replicationEnabled = pulumi
            .output(args.enableCrossRegionReplication ?? false);

        // The resources are created conditionally from the Pulumi stack value.
        // For this component's normal usage this input is a plain boolean.
        if (args.enableCrossRegionReplication === true) {
            const replicaProvider = new aws.Provider(
                `${name}-replica-provider`,
                {
                    region: "us-west-2",
                },
                childOptions,
            );

            this.replicaBucket = new aws.s3.BucketV2(
                `${name}-assets-replica`,
                {
                    tags,
                },
                {
                    parent: this,
                    provider: replicaProvider,
                },
            );

            const replicaVersioning = new aws.s3.BucketVersioningV2(
                `${name}-assets-replica-versioning`,
                {
                    bucket: this.replicaBucket.id,
                    versioningConfiguration: {
                        status: "Enabled",
                    },
                },
                {
                    parent: this,
                    provider: replicaProvider,
                },
            );

            new aws.s3.BucketServerSideEncryptionConfigurationV2(
                `${name}-assets-replica-encryption`,
                {
                    bucket: this.replicaBucket.id,
                    rules: [{
                        applyServerSideEncryptionByDefault: {
                            sseAlgorithm: "AES256",
                        },
                        bucketKeyEnabled: true,
                    }],
                },
                {
                    parent: this,
                    provider: replicaProvider,
                },
            );

            new aws.s3.BucketPublicAccessBlock(
                `${name}-assets-replica-public-access`,
                {
                    bucket: this.replicaBucket.id,
                    blockPublicAcls: true,
                    blockPublicPolicy: true,
                    ignorePublicAcls: true,
                    restrictPublicBuckets: true,
                },
                {
                    parent: this,
                    provider: replicaProvider,
                },
            );

            const replicationRole = new aws.iam.Role(
                `${name}-replication`,
                {
                    assumeRolePolicy: aws.iam.getPolicyDocumentOutput({
                        statements: [{
                            effect: "Allow",
                            actions: ["sts:AssumeRole"],
                            principals: [{
                                type: "Service",
                                identifiers: ["s3.amazonaws.com"],
                            }],
                        }],
                    }).json,
                    tags,
                },
                childOptions,
            );

            const replicationPolicyDocument = aws.iam.getPolicyDocumentOutput({
                statements: [
                    {
                        effect: "Allow",
                        actions: [
                            "s3:GetReplicationConfiguration",
                            "s3:ListBucket",
                        ],
                        resources: [this.assetsBucket.arn],
                    },
                    {
                        effect: "Allow",
                        actions: [
                            "s3:GetObjectVersion",
                            "s3:GetObjectVersionAcl",
                            "s3:GetObjectVersionForReplication",
                            "s3:GetObjectVersionTagging",
                        ],
                        resources: [
                            pulumi.interpolate`${this.assetsBucket.arn}/*`,
                        ],
                    },
                    {
                        effect: "Allow",
                        actions: [
                            "s3:ReplicateDelete",
                            "s3:ReplicateObject",
                            "s3:ReplicateTags",
                        ],
                        resources: [
                            pulumi.interpolate`${this.replicaBucket.arn}/*`,
                        ],
                    },
                ],
            });

            const replicationPolicy = new aws.iam.Policy(
                `${name}-replication`,
                {
                    policy: replicationPolicyDocument.json,
                    tags,
                },
                childOptions,
            );

            const replicationAttachment = new aws.iam.RolePolicyAttachment(
                `${name}-replication`,
                {
                    role: replicationRole.name,
                    policyArn: replicationPolicy.arn,
                },
                childOptions,
            );

            new aws.s3.BucketReplicationConfig(
                `${name}-assets-replication`,
                {
                    bucket: this.assetsBucket.id,
                    role: replicationRole.arn,
                    rules: [{
                        id: "replicate-to-us-west-2",
                        status: "Enabled",
                        priority: 1,
                        filter: {
                            prefix: "",
                        },
                        destination: {
                            bucket: this.replicaBucket.arn,
                            storageClass: "STANDARD",
                        },
                        deleteMarkerReplication: {
                            status: "Enabled",
                        },
                    }],
                },
                {
                    parent: this,
                    dependsOn: [
                        assetsVersioning,
                        replicaVersioning,
                        replicationAttachment,
                    ],
                },
            );
        }

        this.registerOutputs({
            assetsBucketName: this.assetsBucket.bucket,
            assetsBucketArn: this.assetsBucket.arn,
            replicaBucketName: this.replicaBucket?.bucket,
            databaseEndpoint: this.database.endpoint,
            databaseConnectionString: this.databaseConnectionString,
            serviceAccountRoleArn: this.serviceAccountRole.arn,
            replicationEnabled,
        });
    }
}
```

## `index.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import { ApplicationInfrastructure } from "./components/application-infrastructure";

const config = new pulumi.Config();
const stack = pulumi.getStack();

if (stack !== "dev" && stack !== "prod") {
    throw new Error(`Expected stack "dev" or "prod", received "${stack}"`);
}

const environment = stack as "dev" | "prod";
const isProd = environment === "prod";

const infrastructure = new ApplicationInfrastructure("webapp", {
    environment,

    vpcId: config.require("vpcId"),
    databaseSubnetIds: config.requireObject<string[]>("databaseSubnetIds"),
    applicationSecurityGroupId: config.require("applicationSecurityGroupId"),

    databaseName: config.get("databaseName") ?? "app",
    databaseUsername: config.get("databaseUsername") ?? "app_admin",

    // Pulumi preserves this value as a secret through the component outputs
    // and into the RDS password property.
    databasePassword: config.requireSecret("databasePassword"),

    databaseInstanceClass: isProd ? "db.t3.medium" : "db.t3.micro",
    databaseMultiAz: isProd,
    databaseStorageEncrypted: isProd,

    oidcProviderArn: config.require("oidcProviderArn"),
    oidcIssuerUrl: config.require("oidcIssuerUrl"),

    serviceAccountNamespace: config.get("serviceAccountNamespace") ?? "webapp",
    serviceAccountName: config.get("serviceAccountName") ?? "webapp",

    enableCrossRegionReplication: isProd,

    tags: {
        Application: "webapp",
        Owner: "platform",
    },
});

export const assetsBucketName = infrastructure.assetsBucket.bucket;
export const replicaBucketName = infrastructure.replicaBucket?.bucket;
export const databaseEndpoint = infrastructure.database.endpoint;
export const databaseConnectionString =
    infrastructure.databaseConnectionString;
export const serviceAccountRoleArn =
    infrastructure.serviceAccountRole.arn;
```

